import { Point } from '@influxdata/influxdb-client';
import { BadRequestException, InternalServerErrorException } from '@nestjs/common';
import { ApiHideProperty, ApiProperty } from '@nestjs/swagger';
import { IsArray, IsEnum, IsNotEmpty, IsOptional, IsString, Matches, Validate } from 'class-validator';
import { aggregationType } from '../../dimensions/entities/dimensions.entity';

import { InfluxService } from '../../influx/influx.service';
import { CreateUserDto } from '../../users/dto/create-user.dto';
import { measurementMode } from '../dto/create-measurement-config.dto';
import { ReadMeasurementResponseData } from '../dto/read-measurement-config.dto';
import { ValidIAMRole } from '../../setting/dto/customIAMAuthorizer';
import { S3 } from '@aws-sdk/client-s3';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand, GetRoleCommand, UpdateAssumeRolePolicyCommand, NoSuchEntityException } from '@aws-sdk/client-iam';
import { randomUUID } from 'crypto';

export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying resource type which paigo connects to. Default is s3.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public datastoreType?: SupportedDatastores;

    /**
     * The cloud platform where the datastore is hosted. Default is "s3" for S3.
     *
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 's3' })
    public platform?: string;

    /**
     * The AWS region where the S3 bucket is located. Default is "us-east-1".
     *
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    /**
     *
     * Whether paigo is hosting the ingestion endpoint, or it is hosted by the client. Optional, default is `true`.
     * @example 'true'
     */
    @IsString()
    @IsOptional()
    public paigoHosted?: 'true';

    /**
     * What is the cloud environment associated with the ingestion endpoint. Optional, default is `aws`.
     * @example "aws"
     */
    @IsEnum(supportedCloudPlatforms)
    @IsOptional()
    public hostedCloud?: supportedCloudPlatforms;

    /**
     * The Unique ID for the cloud env where the resource is hosted. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    public cloudId: string;

    /**
     * The customer's AWS account ID. Required for datastoreBased mode.
     * @example "123456789012"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: '123456789012' })
    public accountId?: string;

    /**
     * The IAM role ARN created for this measurement. Generated during provisioning.
     * @example "arn:aws:iam::123456789012:role/datastore-mybusiness-abc123"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public iamRoleArn?: string;

    /**
     * The external ID used for the IAM role trust policy. Generated during provisioning.
     * @example "ext-abc123"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public externalId?: string;

    /**
     * The S3 ingestion prefix for this measurement. Generated during provisioning.
     * @example "s3://paigo-usage-record-dump-bucket/mybusiness/measurement-id/"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public ingestion?: string;

    /**
     * The S3 DLQ prefix for this measurement. Generated during provisioning.
     * @example "s3://paigo-usage-record-dlq-bucket/mybusiness/measurement-id/"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { cloudId, hostedCloud, paigoHosted, datastoreType, businessID, accountId, platform, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            this.cloudId = cloudId;
            this.hostedCloud = hostedCloud ? hostedCloud : supportedCloudPlatforms.aws;
            this.paigoHosted = paigoHosted ? paigoHosted : 'true';
            this.datastoreType = datastoreType ? datastoreType : SupportedDatastores.s3;
            this.platform = platform ? platform : 's3';
            this.region = region ? region : 'us-east-1';
            this.businessID = businessID;
            this.accountId = accountId;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { datastoreType: supportedDbs, paigoHosted, hostedCloud, cloudId, accountId, platform, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            if (supportedDbs) influxPoint.tag('supportedDbs', supportedDbs);
            if (paigoHosted) influxPoint.tag('paigoHosted', paigoHosted);
            if (hostedCloud) influxPoint.tag('hostedCloud', hostedCloud);
            if (cloudId) influxPoint.tag('cloudId', cloudId);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (platform) influxPoint.tag('platform', platform);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        datastoreType,
        paigoHosted,
        hostedCloud,
        cloudId,
        businessID,
        accountId,
        platform,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            datastoreType,
            paigoHosted,
            hostedCloud,
            cloudId,
            businessID,
            accountId,
            platform,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
        });
    }
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID, measurementId, accountId, platform, region } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3 && platform === 's3') {
            try {
                // Provision IAM role and policy for S3 ingestion
                await DatastoreAccessInformation.provisionIAMRoleAndPolicy(dbAccessInformation);
            } catch (e) {
                if (e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`CloudId: ${cloudId} is invalid`);
                } else {
                    throw e;
                }
            }
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID, measurementId, accountId, iamRoleArn, externalId, platform } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3 && platform === 's3' && iamRoleArn && externalId) {
            try {
                // Update IAM role trust policy with new account ID
                await DatastoreAccessInformation.updateIAMRoleTrustPolicy(dbAccessInformation);
            } catch (e) {
                throw e;
            }
        }
    }

    private static async provisionIAMRoleAndPolicy(dbAccessInformation: DatastoreAccessInformation) {
        const { businessID, measurementId, accountId, cloudId, region } = dbAccessInformation;
        const roleName = `datastore-${businessID}-${measurementId}`;
        const externalId = `ext-${randomUUID().slice(0, 8)}`;
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        const awsRegion = region || process.env.AWS_REGION || 'us-east-1';

        const iamClient = new IAMClient({ region: awsRegion });

        // Create trust policy
        const trustPolicy = {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };

        // Create the IAM role
        try {
            await iamClient.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                    Description: `Paigo datastore-based measurement role for business ${businessID}, measurement ${measurementId}`,
                })
            );
        } catch (e) {
            if (e instanceof NoSuchEntityException || e.name === 'EntityAlreadyExists') {
                // Role already exists, get its ARN
                const roleResponse = await iamClient.send(new GetRoleCommand({ RoleName: roleName }));
                dbAccessInformation.iamRoleArn = roleResponse.Role?.Arn;
                dbAccessInformation.externalId = externalId;
            } else {
                throw e;
            }
        }

        // Get role ARN if not already set
        if (!dbAccessInformation.iamRoleArn) {
            const roleResponse = await iamClient.send(new GetRoleCommand({ RoleName: roleName }));
            dbAccessInformation.iamRoleArn = roleResponse.Role?.Arn;
        }

        // Create inline policy for S3 access
        const policyDocument = {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
                    Resource: [
                        `arn:aws:s3:::${ingestionBucket}`,
                        `arn:aws:s3:::${ingestionBucket}/${businessID}/*`,
                        `arn:aws:s3:::${dlqBucket}`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
            ],
        };

        await iamClient.send(
            new PutRolePolicyCommand({
                RoleName: roleName,
                PolicyName: 'PaigoS3Access',
                PolicyDocument: JSON.stringify(policyDocument),
            })
        );

        // Set the generated values
        dbAccessInformation.externalId = externalId;
        dbAccessInformation.ingestion = `s3://${ingestionBucket}/${businessID}/${measurementId}/`;
        dbAccessInformation.dlq = `s3://${dlqBucket}/${businessID}/${measurementId}/`;
        dbAccessInformation.region = awsRegion;
    }

    private static async updateIAMRoleTrustPolicy(dbAccessInformation: DatastoreAccessInformation) {
        const { iamRoleArn, accountId, externalId, region } = dbAccessInformation;
        const roleName = iamRoleArn.split('/').pop();
        const awsRegion = region || process.env.AWS_REGION || 'us-east-1';

        const iamClient = new IAMClient({ region: awsRegion });

        // Update trust policy with new account ID but preserve external ID
        const trustPolicy = {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };

        await iamClient.send(
            new UpdateAssumeRolePolicyCommand({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(trustPolicy),
            })
        );
    }

